import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import type { Attributes } from "../attributes";
import { calculateARDetail, displayAR, type AttackResult } from "../calculateAR";
import type { RegulationData } from "../regulationData";
import { allDamageTypes } from "../weapon";
import { makeBuilder } from "./buildWeapon";

// Fixed reference outputs, not generated by our engine. Provenance and update
// instructions: docs/golden-tests.md. No reference checkout is needed to run these.
const data: RegulationData = JSON.parse(
  readFileSync(resolve("public/data/regulation-vanilla-v1.17.json"), "utf8")
);
const build = makeBuilder(data);
const defaults: Attributes = {
  vig: 20, mnd: 10, end: 20, str: 12, dex: 24, int: 40, fai: 10, arc: 10,
};

function weaponNamed(name: string) {
  const matches = data.weapons.filter((weapon) => weapon.name === name);
  expect(matches, `Expected exactly one raw weapon named ${name}`).toHaveLength(1);
  return build(matches[0]);
}

function result(name: string, level: number, stats: Partial<Attributes> = {}, twoHanding = false) {
  return calculateARDetail(weaponNamed(name), { ...defaults, ...stats }, level, twoHanding);
}

// Check the complete set of damage types as well as their unrounded values.
function expectDamage(detail: ReturnType<typeof result>, expected: AttackResult) {
  expect(Object.keys(detail.damage).sort()).toEqual(Object.keys(expected).sort());
  for (const type of allDamageTypes) {
    if (expected[type] !== undefined) {
      expect(detail.damage[type]!.total, type).toBeCloseTo(expected[type]!, 8);
    }
  }
}

describe("patch 1.17 golden integration: regulation JSON → builder → calculation", () => {
  it.each([
    { level: 0, stats: { str: 18, dex: 18 }, physical: 141.1625, base: 115 },
    { level: 25, stats: {}, physical: 382.0479996743574, base: 281.75 },
  ])("builds regular Uchigatana at +$level", ({ level, stats, physical, base }) => {
    const weapon = weaponNamed("Uchigatana");
    expect(weapon.attack).toHaveLength(26);
    const detail = calculateARDetail(weapon, { ...defaults, ...stats }, level);
    expectDamage(detail, { physical });
    expect(detail.damage.physical!.base).toBeCloseTo(base, 8);
    expect(detail.status).toEqual({ bleed: { base: 45, total: 45, penalized: false } });
    expect(detail.spell).toEqual({});
    expect(detail.unmet).toEqual([]);
  });

  it("builds somber Moonveil +10 and preserves split-damage rounding", () => {
    expect(weaponNamed("Moonveil").attack).toHaveLength(11);
    const detail = result("Moonveil", 10);
    expectDamage(detail, { physical: 238.41127730624882, magic: 366.618 });
    expect(detail.status.bleed).toEqual({ base: 50, total: 50, penalized: false });
    expect(detail.unmet).toEqual([]);
    expect(displayAR({ physical: detail.damage.physical!.total, magic: detail.damage.magic!.total }))
      .toEqual({ parts: { physical: 238, magic: 366 }, total: 605 });
  });

  it.each([
    { int: 22, magic: 127.89, unmet: ["int"], penalized: true },
    { int: 23, magic: 314.43888, unmet: [], penalized: false },
  ])("Moonveil at Int $int applies only the affected element's penalty", ({ int, magic, unmet, penalized }) => {
    const detail = result("Moonveil", 10, { int });
    expectDamage(detail, { physical: 238.41127730624882, magic });
    expect(detail.unmet).toEqual(unmet);
    expect(detail.damage.magic!.penalized).toBe(penalized);
    expect(detail.damage.physical!.penalized).toBe(false);
  });

  it.each([
    { arc: 12, physical: 81.765, bleed: 30, unmet: ["arc"], penalized: true },
    { arc: 13, physical: 191.23458250868327, bleed: 51.925, unmet: [], penalized: false },
  ])("Reduvia +5 at Arc $arc checks the requirement boundary and status curve", ({ arc, physical, bleed, unmet, penalized }) => {
    const detail = result("Reduvia", 5, { int: 10, arc });
    expectDamage(detail, { physical });
    expect(detail.unmet).toEqual(unmet);
    expect(detail.damage.physical!.penalized).toBe(penalized);
    expect(Object.keys(detail.status)).toEqual(["bleed"]);
    expect(detail.status.bleed!.base).toBe(50);
    expect(detail.status.bleed!.total).toBeCloseTo(bleed, 8);
    expect(detail.status.bleed!.penalized).toBe(penalized);
  });

  it("Reduvia +10 scales bleed at high Arcane", () => {
    const detail = result("Reduvia", 10, { int: 10, arc: 60 });
    expectDamage(detail, { physical: 398.9843009868583 });
    expect(detail.status.bleed!.total).toBeCloseTo(94.55, 8);
    expect(detail.status.bleed!.penalized).toBe(false);
  });

  it.each([
    { level: 0, physical: 112.43375, magic: 94.74666666666666, frost: 66 },
    { level: 12, physical: 189.042194, magic: 163.35099733333337, frost: 85 },
    { level: 25, physical: 274.1805, magic: 242.88, frost: 105 },
  ])("Cold Uchigatana +$level joins upgrade-dependent status parameters", ({ level, physical, magic, frost }) => {
    const detail = result("Cold Uchigatana", level, { str: 18, dex: 18, arc: 60 });
    expectDamage(detail, { physical, magic });
    expect(detail.status).toEqual({
      bleed: { base: 38, total: 38, penalized: false },
      frost: { base: frost, total: frost, penalized: false },
    });
  });

  it.each([false, true])("paired Star Fist does not gain Strength (twoHanding=%s)", (twoHanding) => {
    expect(weaponNamed("Star Fist").paired).toBe(true);
    const detail = result("Star Fist", 25, { str: 20, dex: 20, int: 10 }, twoHanding);
    expectDamage(detail, { physical: 335.681615117996 });
    expect(detail.unmet).toEqual([]);
  });

  it.each([false, true])("Longbow always gains Strength to satisfy its requirement (twoHanding=%s)", (twoHanding) => {
    const detail = result("Longbow", 25, { str: 6, dex: 20, int: 10 }, twoHanding);
    expectDamage(detail, { physical: 223.23304920597323 });
    expect(detail.unmet).toEqual([]);
    expect(detail.damage.physical!.penalized).toBe(false);
    expect(detail.status).toEqual({});
  });

  it("two-handed Strength 99 uses the real curve at 148", () => {
    const detail = result("Uchigatana", 25, { str: 99, dex: 18, int: 10 }, true);
    expectDamage(detail, { physical: 506.3510375 });
    expect(detail.unmet).toEqual([]);
  });

  it("Finger Seal reports every element's scaling without inventing base damage", () => {
    const weapon = weaponNamed("Finger Seal");
    expect(weapon.incantationTool).toBe(true);
    const detail = result("Finger Seal", 25, { dex: 12, int: 10, fai: 40 });
    expectDamage(detail, { physical: 96.921875 });
    expect(Object.keys(detail.spell).sort()).toEqual([...allDamageTypes].sort());
    for (const type of allDamageTypes) {
      expect(detail.spell[type]!.scaling, type).toBeCloseTo(221.5357142857143, 8);
      expect(detail.spell[type]!.penalized).toBe(false);
    }
    expect(detail.unmet).toEqual([]);
  });

  it("Flame Art Smithscript Greathammer retains numeric attribute corrections", () => {
    const weapon = weaponNamed("Flame Art Smithscript Greathammer");
    expect(weapon.dlc).toBe(true);
    expect(weapon.attackElementCorrect.physical!.int).toBe(0.05);
    expect(weapon.attackElementCorrect.physical!.fai).toBe(0.05);
    const detail = calculateARDetail(weapon, { ...defaults, str: 40, dex: 20, int: 20, fai: 20 }, 25);
    expectDamage(detail, { physical: 346.50436141917885, fire: 346.7576 });
    expect(detail.unmet).toEqual([]);
    expect(detail.status).toEqual({});
  });
});
